'use strict';

window.AUR.shipModule('petrel/survey-ring', function (use) {
const { Vector3 } = BABYLON;
const { TransformNode } = BABYLON;
const { Assembly, v } = use('petrel/geometry');

// Petrel looks along +Z. The wheel lies in XY, forward of the four hull sockets.
const RING = { radius: 9.50, inner: 7.78, y: -.26, z: 1.48, halfDepth: .64 };
const bays = 24;
const tau = 2*Math.PI;
const stops = [0,.012,.082,.10,.24,.38,.50,.62,.76,.90,.918,.988,1];
const radial = angle => v(Math.cos(angle),Math.sin(angle),0);
const axial = Vector3.Forward();
const ringPoint = (direction,r,z) => v(r*direction.x,RING.y+r*direction.y,RING.z+z);

// Travel around the actual section. Each entry names the surface leading to the next station.
function buildRim(part,m) {
  const {inner,radius,halfDepth}=RING;
  /** @type {[number, number, string][]} radius, axial offset, surface */
  const front=[
    [inner,.27,'steel'],[inner,.34,'rail'],[inner+.135,.50,'rim'],
    [inner+.17,.526,'pearl'],[inner+.245,halfDepth,'panel'],
    [radius-.28,halfDepth,'wingSkin'],[radius-.073,.50,'pearl'],[radius,.37,'panel'],
  ];
  const back=front.map(/** @returns {[number, number, string]} */ ([r,z],i)=>[r,-z,i ? front[i-1][2] : 'iron']).reverse();
  const profile=front.concat(back);
  const sections=profile.map(([r,z,key],i)=>{
    const [nextR,nextZ]=profile[(i+1)%profile.length];
    const dr=nextR-r,dz=nextZ-z,length=Math.hypot(dr,dz);
    return {r,z,key,dr,dz,nr:-dz/length,nz:dr/length};
  });
  for (let bay=0;bay<bays;bay++) {
    for (let i=1;i<stops.length;i++) {
      const u0=stops[i-1],u1=stops[i];
      const directions=[u0,u1].map(u=>radial((bay-.5+u)*tau/bays));
      for (const {r,z,key,dr,dz,nr,nz} of sections) {
        const normals=directions.map(p=>v(nr*p.x,nr*p.y,nz));
        const skin=key==='panel', solar=skin && bay%3!==0;
        const rows=solar ? [0,.12,.15,.85,.88,1] : [0,1];
        for (let k=1;k<rows.length;k++) {
          const t0=rows[k-1],t1=rows[k], uMid=(u0+u1)/2, tMid=(t0+t1)/2;
          const inset=solar && uMid>.082 && uMid<.918 && tMid>.12 && tMid<.88;
          const wafer=inset && uMid>.10 && uMid<.90 && tMid>.15 && tMid<.85;
          const service=bay%6===0 && uMid>.38 && uMid<.62;
          let finish=m[key];
          if (wafer) finish=m.wafers;
          else if (inset) finish=m.rim;
          else if (service && skin) finish=m.rail;
          else if (service && (key==='wingSkin' || key==='pearl')) finish=m.iron;
          const corners=[[0,u0,t0],[1,u1,t0],[1,u1,t1],[0,u0,t1]];
          const points=corners.map(([end,u,t])=>{
            const recess=solar && u>=.10 && u<=.90 && t>=.15 && t<=.85 ? -.035 : 0;
            return ringPoint(directions[end],r+dr*t+nr*recess,z+dz*t+nz*recess);
          });
          const uvs=corners.map(([,u,t])=>{
            if (wafer) return [(u-.10)/.80,.20+.30*(t-.15)/.70];
            if (service && skin) return [t,(u-.38)/.24];
            return [u,t];
          });
          // The narrow perimeter facets catch light around each recessed wafer.
          part.face(finish,points,normals[0],inset && !wafer ? null : [normals[0],normals[1],normals[1],normals[0]],uvs);
        }
      }
    }
  }
}

// A turned piece changes radius only at a machining station; each material starts on the previous edge.
function turned(part,origin,axis,stations) {
  const side=Vector3.Cross(axial,axis).normalize(), other=Vector3.Cross(axis,side);
  const directions=Array.from({length:32},(_,i)=>side.scale(Math.cos(i*tau/32)).add(other.scale(Math.sin(i*tau/32))));
  const circle=(h,r)=>directions.map(rad=>origin.add(axis.scale(h)).addInPlace(rad.scale(r)));
  let last=circle(stations[0][0],stations[0][1]);
  for (let i=1;i<stations.length;i++) {
    const [h,r,finish]=stations[i], next=circle(h,r);
    part.sleeve(last,next,finish,{smooth:true,inside:h<stations[i-1][0]});
    last=next;
  }
}

function buildArm(part,m,{center,normal}) {
  const angle=Math.atan2(Math.sign(center.y-RING.y),Math.sign(center.x));
  const outward=radial(angle), anchor=ringPoint(outward,RING.inner,0);
  const pivot=center.add(normal.scale(.13));
  const line=anchor.subtract(pivot), length=line.length(), axis=line.scale(1/length);
  // The plug fits inside the original .143-unit bezel. Its larger shoulder rests above the skin.
  turned(part,center,normal,[
    [-.067,.088],[.019,.088,m.steel],[.039,.188,m.steel],[.068,.194,m.silver],
    [.084,.177,m.silver],[.104,.15,m.black],[.142,.132,m.steel],[.15,.075,m.steel],
  ]);
  const end=length-.46;
  turned(part,pivot,axis,[
    [-.018,.090],[.046,.144,m.iron],[.088,.158,m.silver],[.17,.158,m.steel],
    [.19,.141,m.silver],[.39,.141,m.steel],[.42,.123,m.silver],[.44,.109,m.iron],
    [end-.62,.109,m.shaft],[end-.59,.143,m.steel],[end-.43,.143,m.silver],
    [end-.40,.184,m.rim],[end-.26,.204,m.rim],[end-.23,.198,m.iron],
    [end-.21,.233,m.rim],[end-.089,.253,m.rim],[end-.070,.280,m.iron],[end,.289,m.rim],
  ]);

  // The foot follows the circular inner wall; its front plate is perpendicular to the pull arm.
  const tangent=v(-outward.y,outward.x,0);
  const across=Vector3.Cross(axial,axis).normalize();
  const depth=Vector3.Cross(axis,across).normalize();
  const face=anchor.subtract(axis.scale(.46)), stages=[[],[],[],[]];
  const rounded=n=>Math.sign(n)*Math.abs(n)**.42;
  for (let i=0;i<32;i++) {
    const a=i*tau/32, x=Math.cos(a), y=Math.sin(a), sx=rounded(x), sy=rounded(y);
    stages[0].push(ringPoint(radial(angle+.53*sx/RING.inner),RING.inner,.266*sy));
    stages[1].push(anchor.subtract(outward.scale(.09)).add(tangent.scale(.51*sx)).add(axial.scale(.34*sy)));
    stages[2].push(face.add(across.scale(.416*sx)).addInPlace(depth.scale(.327*sy)));
    stages[3].push(face.add(across.scale(.289*x)).addInPlace(depth.scale(.289*y)));
  }
  part.sleeve(stages[0],stages[1],m.iron);
  part.sleeve(stages[1],stages[2],m.mount);
  for (let i=0;i<32;i++) {
    const j=(i+1)%32;
    part.face(m.mount,[stages[2][i],stages[2][j],stages[3][j],stages[3][i]],axis.negate());
  }
  for (const x of [-.30,.30]) for (const y of [-.215,.215]) {
    const screw=face.add(across.scale(x)).addInPlace(depth.scale(y));
    turned(part,screw,axis.negate(),[[0,.035],[.009,.032,m.steel],[.010,.016,m.silver],[.008,0,m.iron]]);
  }
}

function createSurveyRing(scene,parent,sockets,materials) {
  const root=new TransformNode('Petrel survey ring',scene);
  root.parent=parent;
  const part=new Assembly(scene,root);
  buildRim(part,materials);
  for (const socket of sockets) buildArm(part,materials,socket);
  part.finish();
  return root;
}
return { RING, createSurveyRing, ringPoint };
});
